import java.util.Scanner;
import java.util.Locale;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int C = sc.nextInt();
        int D = sc.nextInt();
        int T = sc.nextInt();

        double ans;
        if (C * T >= D) {
            ans = 0.0;
        } else {
            ans = (D - C * T) / (double) C;
        }

        System.out.printf(Locale.US, "%.1f\n", ans);
    }
}
